input.new_string:
import { greet } from "./greet";

describe("greet", () => {
  describe("typical use cases", () => {
    it.each([
      ["World", "Hello, World!"],
      ["Alice", "Hello, Alice!"],
      ["Bob", "Hello, Bob!"],
      ["Charlie", "Hello, Charlie!"],
    ])("should return greeting for name '%s'", (name, expected) => {
      expect(greet(name)).toBe(expected);
    });
  });

  describe("edge cases", () => {
    it("should handle empty string", () => {
      const result = greet("");
      expect(result).toBe("Hello, !");
      expect(result).toMatch(/^Hello, .*!$/);
    });

    it("should handle special characters", () => {
      const result = greet("Alice@123");
      expect(result).toBe("Hello, Alice@123!");
      expect(result).toMatch(/^Hello, .*!$/);
    });

    it("should handle names with spaces", () => {
      const result = greet("John Doe");
      expect(result).toBe("Hello, John Doe!");
      expect(result).toMatch(/^Hello, .*!$/);
    });

    it("should handle very long strings", () => {
      const longName = "A".repeat(1000);
      const result = greet(longName);
      expect(result).toBe(`Hello, ${longName}!`);
      expect(result).toMatch(/^Hello, .*!$/);
    });

    it("should handle unicode characters", () => {
      const result = greet("José");
      expect(result).toBe("Hello, José!");
      expect(result).toMatch(/^Hello, .*!$/);
    });
  });

  describe("output format validation", () => {
    it.each([
      "World",
      "Alice",
      "",
      "Special!@#$",
      "Very long name ".repeat(10),
    ])("should maintain format 'Hello, <name>!' for input '%s'", (name) => {
      const result = greet(name);
      expect(result).toMatch(/^Hello, .*!$/);
      expect(result).toStartWith("Hello, ");
      expect(result).toEndWith("!");
    });
  });
});

