import { greet } from './greet';

describe('greet', () => {
	it('should return "Hello, World!" when called with "World"', () => {
		expect(greet('World')).toBe('Hello, World!');
	});

	describe('with various input names', () => {
		it.each([
			['Alice', 'Hello, Alice!'],
			['Bob', 'Hello, Bob!'],
			['Charlie', 'Hello, Charlie!'],
			['', 'Hello, !'],
			['Alice Smith', 'Hello, Alice Smith!'],
			['  ', 'Hello,   !'],
			['John123', 'Hello, John123!'],
			['Mary-Jane', 'Hello, Mary-Jane!'],
			['A', 'Hello, A!'],
			['verylongnamethathasmanycharsinthetexthere', 'Hello, verylongnamethathasmanycharsinthetexthere!'],
		])('should greet %s and return %s', (name, expected) => {
			expect(greet(name)).toBe(expected);
		});
	});

	describe('edge cases', () => {
		it('should handle empty string input', () => {
			expect(greet('')).toBe('Hello, !');
		});

		it('should handle whitespace-only string', () => {
			expect(greet('   ')).toBe('Hello,    !');
		});

		it('should handle names with special characters', () => {
			expect(greet('José')).toBe('Hello, José!');
		});

		it('should handle names with punctuation', () => {
			expect(greet("O'Brien")).toBe("Hello, O'Brien!");
		});

		it('should handle names with numbers', () => {
			expect(greet('R2D2')).toBe('Hello, R2D2!');
		});

		it('should handle very long names', () => {
			const longName = 'a'.repeat(1000);
			expect(greet(longName)).toBe(`Hello, ${longName}!`);
		});
	});
});

