import { test, expect, describe } from "bun:test";
import { greet } from "./greet";

describe("greet", () => {
  describe("happy path", () => {
    test("returns correct greeting for normal name", () => {
      expect(greet("World")).toBe("Hello, World!");
    });

    test("returns correct greeting for single character", () => {
      expect(greet("A")).toBe("Hello, A!");
    });

    test("returns correct greeting for common name", () => {
      expect(greet("Alice")).toBe("Hello, Alice!");
    });
  });

  describe("empty and whitespace inputs", () => {
    test("handles empty string", () => {
      expect(greet("")).toBe("Hello, !");
    });

    test("handles whitespace-only string", () => {
      expect(greet("   ")).toBe("Hello,    !");
    });

    test("handles tab character", () => {
      expect(greet("\t")).toBe("Hello, \t!");
    });

    test("preserves leading and trailing whitespace", () => {
      expect(greet("  Alice  ")).toBe("Hello,   Alice  !");
    });
  });

  describe("special characters and numbers", () => {
    test("handles names with hyphens", () => {
      expect(greet("Mary-Jane")).toBe("Hello, Mary-Jane!");
    });

    test("handles names with apostrophes", () => {
      expect(greet("O'Brien")).toBe("Hello, O'Brien!");
    });

    test("handles names with numbers", () => {
      expect(greet("Agent007")).toBe("Hello, Agent007!");
    });

    test("handles names with at symbol", () => {
      expect(greet("@user")).toBe("Hello, @user!");
    });

    test("handles names with multiple special characters", () => {
      expect(greet("Test-123_@User")).toBe("Hello, Test-123_@User!");
    });
  });

  describe("unicode and international characters", () => {
    test("handles accented characters", () => {
      expect(greet("José")).toBe("Hello, José!");
    });

    test("handles umlauts", () => {
      expect(greet("Müller")).toBe("Hello, Müller!");
    });

    test("handles Chinese characters", () => {
      expect(greet("李明")).toBe("Hello, 李明!");
    });

    test("handles Cyrillic characters", () => {
      expect(greet("Иван")).toBe("Hello, Иван!");
    });
  });

  describe("boundary cases", () => {
    test("handles very long name", () => {
      const longName = "A".repeat(1000);
      expect(greet(longName)).toBe(`Hello, ${longName}!`);
    });

    test("handles name with mixed case", () => {
      expect(greet("JoHn DoE")).toBe("Hello, JoHn DoE!");
    });
  });
});

