  describe("boundary cases", () => {
    test("handles very long name", () => {
      const longName = "A".repeat(1000);
      expect(greet(longName)).toBe(`Hello, ${longName}!`);
    });

    test("handles name with mixed case", () => {
      expect(greet("JoHn DoE")).toBe("Hello, JoHn DoE!");
    });

    test("handles extremely long repeated character string", () => {
      const veryLongRepeated = "x".repeat(10000);
      expect(greet(veryLongRepeated)).toBe(`Hello, ${veryLongRepeated}!`);
    });

    test("handles name consisting of repeated digits", () => {
      const repeatedDigits = "9".repeat(100);
      expect(greet(repeatedDigits)).toBe(`Hello, ${repeatedDigits}!`);
    });
  });

  describe("null and undefined handling", () => {
    test("documents behavior with null input (type safety)", () => {
      // TypeScript prevents this at compile time, but verifying runtime behavior
      // if null were somehow passed: function should concatenate directly
      const result = greet(null as unknown as string);
      expect(result).toBe("Hello, null!");
    });

    test("documents behavior with undefined input (type safety)", () => {
      // TypeScript prevents this at compile time, but verifying runtime behavior
      // if undefined were somehow passed: function should concatenate directly
      const result = greet(undefined as unknown as string);
      expect(result).toBe("Hello, undefined!");
    });
  });

  describe("whitespace edge cases", () => {
    test("handles newline character in name", () => {
      expect(greet("John\nDoe")).toBe("Hello, John\nDoe!");
    });

    test("handles carriage return character", () => {
      expect(greet("Test\r")).toBe("Hello, Test\r!");
    });

    test("handles mixed whitespace (space, tab, newline)", () => {
      expect(greet("A \t\nB")).toBe("Hello, A \t\nB!");
    });

    test("preserves exactly one leading space", () => {
      expect(greet(" Single")).toBe("Hello,  Single!");
    });

    test("preserves multiple consecutive spaces within name", () => {
      expect(greet("John    Doe")).toBe("Hello, John    Doe!");
    });
  });
});

