import { greet } from './greet';

describe('greet', () => {
  describe('happy path - standard inputs', () => {
    it('should return "Hello, World!" when called with "World"', () => {
      const result = greet('World');
      expect(result).toBe('Hello, World!');
    });

    it('should return "Hello, Alice!" when called with "Alice"', () => {
      const result = greet('Alice');
      expect(result).toBe('Hello, Alice!');
    });

    it('should return "Hello, Bob!" when called with "Bob"', () => {
      const result = greet('Bob');
      expect(result).toBe('Hello, Bob!');
    });
  });

  describe('edge cases - boundary conditions', () => {
    it('should handle single character names', () => {
      const result = greet('A');
      expect(result).toBe('Hello, A!');
    });

    it('should handle empty strings', () => {
      const result = greet('');
      expect(result).toBe('Hello, !');
    });

    it('should handle very long strings', () => {
      const longName = 'A'.repeat(1000);
      const result = greet(longName);
      expect(result).toBe(`Hello, ${longName}!`);
    });
  });

  describe('edge cases - special characters', () => {
    it('should handle names with spaces', () => {
      const result = greet('John Doe');
      expect(result).toBe('Hello, John Doe!');
    });

    it('should handle names with special characters', () => {
      const result = greet('O\'Brien');
      expect(result).toBe('Hello, O\'Brien!');
    });

    it('should handle names with punctuation and symbols', () => {
      const result = greet('name@123');
      expect(result).toBe('Hello, name@123!');
    });

    it('should handle whitespace-only inputs', () => {
      const result = greet('   ');
      expect(result).toBe('Hello,    !');
    });
  });

  describe('format validation', () => {
    it('should always follow the "Hello, <name>!" pattern', () => {
      const inputs = ['World', 'Alice', 'Bob', 'Test', 'O\'Brien', 'John Doe', '', '   '];
      inputs.forEach(input => {
        const result = greet(input);
        expect(result).toBe(`Hello, ${input}!`);
        expect(result).toMatch(/^Hello, .*!$/);
      });
    });
  });
});

